@theme {
  --color-paper: #FBF9F5;
  --color-ink: #1E1B2E;
  --color-lavender: #E8E0F8;
  --color-mint: #D9F2E6;
  --color-peach: #FCE2D5;
  --color-accent: #5B46E8;
  --color-mauve: #645D7A;
  --color-rose: #D9385A;

  --font-display: var(--font-urbanist), system-ui, sans-serif;
  --font-body: var(--font-jakarta), system-ui, sans-serif;
  --font-mono: var(--font-jetbrains), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-spring: linear(0, 0.35 8%, 0.82 20%, 1.06 30%, 1.02 42%, 0.99 58%, 1);

  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 800ms;
  --dur-hero: 1200ms;

  --reveal-shift: 28px;
  --stagger: 70ms;
}

:root {
  --color-paper: #FBF9F5;
  --color-ink: #1E1B2E;
  --color-lavender: #E8E0F8;
  --color-mint: #D9F2E6;
  --color-peach: #FCE2D5;
  --color-accent: #5B46E8;
  --color-mauve: #645D7A;
  --color-rose: #D9385A;

  --font-display: var(--font-urbanist), system-ui, sans-serif;
  --font-body: var(--font-jakarta), system-ui, sans-serif;
  --font-mono: var(--font-jetbrains), ui-monospace, monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-spring: linear(0, 0.35 8%, 0.82 20%, 1.06 30%, 1.02 42%, 0.99 58%, 1);

  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 800ms;
  --dur-hero: 1200ms;

  --reveal-shift: 28px;
  --stagger: 70ms;

  --spacing: 0.25rem;
  --container-md: 28rem;
  --container-2xl: 42rem;
  --text-xs: 0.75rem;
  --text-xs--line-height: 1.333333;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.428571;
  --text-base: 1rem;
  --text-base--line-height: 1.5;
  --text-lg: 1.125rem;
  --text-lg--line-height: 1.555556;
  --text-xl: 1.25rem;
  --text-xl--line-height: 1.4;
  --text-2xl: 1.5rem;
  --text-2xl--line-height: 1.333333;
  --text-3xl: 1.875rem;
  --text-3xl--line-height: 1.2;
  --text-4xl: 2.25rem;
  --text-4xl--line-height: 1.111111;
  --text-5xl: 3rem;
  --text-5xl--line-height: 1;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-extrabold: 800;
  --tracking-tight: -0.025em;
  --leading-snug: 1.375;
  --leading-relaxed: 1.625;
  --default-transition-duration: 150ms;
  --default-transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  --tw-border-style: solid;
  --tw-scale-x: 1;
  --tw-scale-y: 1;
  --tw-space-y-reverse: 0;
}

html {
  scroll-padding-top: 112px;
  scroll-behavior: smooth;
  background-color: var(--color-paper);
}

.vl-body {
  background-color: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: clip;
}

.vl-display {
  font-family: var(--font-display);
  letter-spacing: -0.03em;
}

.vl-mono {
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
}

.vl-container {
  width: min(1280px, calc(100% - 2 * clamp(18px, 4.5vw, 60px)));
  margin-inline: auto;
}

/* Smooth pastel slab surfaces & handoffs */
.vl-slab {
  position: relative;
  border-radius: 36px;
  transition: transform var(--dur-slow) var(--ease-out), opacity var(--dur-slow) var(--ease-out);
}

.vl-slab--lavender {
  background: radial-gradient(
    120% 100% at 80% 10%,
    var(--color-lavender) 0%,
    color-mix(in srgb, var(--color-lavender) 58%, var(--color-paper)) 65%,
    var(--color-paper) 100%
  );
}

.vl-slab--mint {
  background: radial-gradient(
    110% 100% at 20% 15%,
    var(--color-mint) 0%,
    color-mix(in srgb, var(--color-mint) 62%, var(--color-paper)) 70%,
    var(--color-paper) 100%
  );
}

.vl-slab--peach {
  background: radial-gradient(
    115% 100% at 75% 20%,
    var(--color-peach) 0%,
    color-mix(in srgb, var(--color-peach) 64%, var(--color-paper)) 72%,
    var(--color-paper) 100%
  );
}

.vl-slab--paper {
  background-color: var(--color-paper);
}

/* Pill & Squircle Geometry */
.vl-pill {
  border-radius: 9999px;
}

.vl-squircle {
  border-radius: 28px;
}

.vl-squircle-lg {
  border-radius: 34px;
}

/* Top scroll progress hairline */
.vl-progress-track {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  z-index: 60;
  background: color-mix(in srgb, var(--color-lavender) 65%, transparent);
  pointer-events: none;
}

.vl-progress-bar {
  height: 100%;
  width: 100%;
  background: var(--color-accent);
  transform-origin: left center;
  transform: scaleX(var(--vl-progress, 0));
  transition: transform var(--dur-instant) linear;
}

/* Floating pill header */
.vl-header {
  position: sticky;
  top: 14px;
  z-index: 50;
  pointer-events: none;
  transition: transform var(--dur-base) var(--ease-out), padding var(--dur-base) var(--ease-out);
}

.vl-header-inner {
  pointer-events: auto;
  border-radius: 9999px;
  background: color-mix(in srgb, var(--color-paper) 88%, var(--color-lavender));
  backdrop-filter: blur(14px);
  border: 1.5px solid color-mix(in srgb, var(--color-ink) 14%, var(--color-lavender));
  box-shadow: 0 12px 32px -12px color-mix(in srgb, var(--color-ink) 10%, transparent);
  padding: 10px 16px;
  transition: padding var(--dur-base) var(--ease-out), background-color var(--dur-base) var(--ease-out);
}

.vl-header[data-scrolled="true"] .vl-header-inner {
  padding-top: 7px;
  padding-bottom: 7px;
  background: color-mix(in srgb, var(--color-paper) 94%, var(--color-lavender));
}

/* Interactive buttons with fill-wipe & spring press */
.vl-btn {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 9999px;
  padding: 13px 24px;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  border: 1.5px solid var(--color-ink);
  transition:
    transform var(--dur-instant) var(--ease-out),
    color var(--dur-fast) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out),
    background-color var(--dur-fast) var(--ease-out);
}

.vl-btn:active:not(:disabled) {
  transform: scale(0.97);
  transition-timing-function: var(--ease-spring);
}

.vl-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.vl-btn--primary {
  background-color: var(--color-accent);
  color: var(--color-paper);
  border-color: var(--color-accent);
}

.vl-btn--primary::before {
  content: "";
  position: absolute;
  inset: 0;
  background-color: var(--color-ink);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform var(--dur-base) var(--ease-out);
  z-index: -1;
  border-radius: inherit;
}

.vl-btn--secondary {
  background-color: var(--color-paper);
  color: var(--color-ink);
  border-color: color-mix(in srgb, var(--color-ink) 24%, transparent);
}

.vl-btn--secondary::before {
  content: "";
  position: absolute;
  inset: 0;
  background-color: var(--color-lavender);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform var(--dur-base) var(--ease-out);
  z-index: -1;
  border-radius: inherit;
}

.vl-btn__arrow {
  display: inline-block;
  transition: transform var(--dur-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .vl-btn--primary:hover:not(:disabled) {
    border-color: var(--color-ink);
  }
  .vl-btn--primary:hover:not(:disabled)::before {
    transform: scaleX(1);
  }
  .vl-btn--secondary:hover:not(:disabled)::before {
    transform: scaleX(1);
  }
  .vl-btn:hover:not(:disabled) .vl-btn__arrow {
    transform: translateX(4px);
  }
}

/* Interactive Tilt & Spotlight Cards */
.vl-card {
  position: relative;
  overflow: hidden;
  border-radius: 28px;
  border: 1.5px solid color-mix(in srgb, var(--color-ink) 12%, transparent);
  background-color: var(--color-paper);
  transition:
    transform var(--dur-base) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out),
    opacity var(--dur-base) var(--ease-out);
  transform: perspective(950px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)) translateY(var(--lift, 0px));
}

.vl-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    280px circle at var(--mx, 50%) var(--my, 50%),
    color-mix(in srgb, var(--color-accent) 18%, transparent),
    transparent 70%
  );
  transition: opacity var(--dur-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .vl-card:hover {
    --lift: -6px;
    border-color: color-mix(in srgb, var(--color-accent) 48%, var(--color-ink));
  }
  .vl-card:hover::after {
    opacity: 1;
  }
  .vl-card-grid:has(.vl-card:hover) .vl-card:not(:hover) {
    opacity: 0.78;
  }
}

/* Pill Form Inputs with floating labels & shake error */
.vl-input-wrap {
  position: relative;
}

.vl-input {
  width: 100%;
  border-radius: 9999px;
  border: 1.5px solid color-mix(in srgb, var(--color-ink) 20%, transparent);
  background-color: var(--color-paper);
  color: var(--color-ink);
  padding: 14px 22px;
  font-family: var(--font-body);
  font-size: 15px;
  transition:
    border-color var(--dur-fast) var(--ease-out),
    background-color var(--dur-fast) var(--ease-out);
}

.vl-input:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-color: var(--color-accent);
}

.vl-input[aria-invalid="true"] {
  border-color: var(--color-rose);
  background-color: color-mix(in srgb, var(--color-rose) 6%, var(--color-paper));
}

@keyframes vl-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  50% { transform: translateX(6px); }
  75% { transform: translateX(-4px); }
}

.vl-shake {
  animation: vl-shake var(--dur-base) var(--ease-out);
}

/* Accordion animation via grid-template-rows */
.vl-accordion-body {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--dur-base) var(--ease-out);
}

.vl-accordion-body[data-open="true"] {
  grid-template-rows: 1fr;
}

.vl-accordion-inner {
  overflow: hidden;
}

/* Marquee */
@keyframes vl-marquee-scroll {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-50%, 0, 0); }
}

.vl-marquee-track {
  display: flex;
  width: max-content;
  animation: vl-marquee-scroll 46s linear infinite;
}

.vl-marquee-track:hover,
.vl-marquee-track:focus-within,
.vl-marquee-track[data-paused="true"] {
  animation-play-state: paused;
}

/* Placeholder art frame */
.vl-placeholder {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 24px;
  overflow: hidden;
  background-color: var(--color-lavender);
  border: 1.5px solid color-mix(in srgb, var(--color-ink) 14%, transparent);
}

/* Visible Focus Ring */
.vl-body :focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

/* Load choreography & Scroll Reveals — ONLY active when motion is allowed and JS set data-vl-motion="live" */
@keyframes vl-hero-drop {
  from {
    opacity: 0;
    transform: translateY(-16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes vl-hero-mask {
  from {
    transform: translateY(105%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes vl-hero-rise {
  from {
    opacity: 0;
    transform: translateY(22px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes vl-float-slow {
  0%, 100% {
    transform: translate3d(0, 0, 0);
  }
  50% {
    transform: translate3d(0, -8px, 0);
  }
}

@media (prefers-reduced-motion: no-preference) {
  html[data-vl-motion="live"] .vl-load-header {
    animation: vl-hero-drop var(--dur-slow) var(--ease-out) 120ms both;
  }

  html[data-vl-motion="live"] .vl-load-mask > span {
    display: block;
    animation: vl-hero-mask var(--dur-slow) var(--ease-out-expo) calc(220ms + var(--i, 0) * 90ms) both;
  }

  html[data-vl-motion="live"] .vl-load-rise {
    animation: vl-hero-rise var(--dur-slow) var(--ease-out) calc(440ms + var(--i, 0) * 80ms) both;
  }

  html[data-vl-motion="live"] .vl-float-badge[data-paused="false"] {
    animation: vl-float-slow 8s var(--ease-in-out) infinite;
  }

  html[data-vl-motion="live"] [data-reveal] {
    transition:
      opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out),
      clip-path var(--dur-slow) var(--ease-in-out);
    transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger));
  }

  html[data-vl-motion="live"] [data-reveal="rise"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(var(--reveal-shift));
  }

  html[data-vl-motion="live"] [data-reveal="scale"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
  }

  html[data-vl-motion="live"] [data-reveal="wipe"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(18px);
    clip-path: inset(0 0 14% 0 round 28px);
  }

  html[data-vl-motion="live"] [data-reveal="wipe"][data-in="true"] {
    opacity: 1;
    transform: translateY(0);
    clip-path: inset(0 0 0% 0 round 28px);
  }

  html[data-vl-motion="live"] [data-reveal="draw"]:not([data-in="true"]) {
    transform: scaleX(0);
    transform-origin: left center;
  }

  html[data-vl-motion="live"] [data-reveal="slide-left"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateX(-24px);
  }

  html[data-vl-motion="live"] [data-reveal="mask"] {
    overflow: clip;
  }

  html[data-vl-motion="live"] [data-reveal="mask"] > .vl-mask-inner {
    display: block;
    transition: transform var(--dur-slow) var(--ease-out-expo);
    transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger));
  }

  html[data-vl-motion="live"] [data-reveal="mask"]:not([data-in="true"]) > .vl-mask-inner {
    transform: translateY(108%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .vl-marquee-track {
    animation: none !important;
  }
  .vl-card {
    transform: none !important;
  }
  [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
    clip-path: none !important;
  }
}

